 Path("JLPT_N1_v177_audit.md").write_text(audit,encoding="utf-8")
 Path("completion/C10-followup-364-416-20261113.md").write_text(audit,encoding="utf-8")
 candidate={"checkpoint":"v177-c10-candidate","base_html":"JLPT_N1_ukrainian_reading_v176.html","base_sha256":prep["base_sha256"],"candidate_html":"JLPT_N1_ukrainian_reading_v177.html","candidate_sha256":h,"scope_ids":[364,371,378,379,380,386,395,402,404,410,415,416],"changed_ids":prep["changed_ids"],"reviewed_without_change":["371"],"pair_indexes":[61,94,99,104],"structural_invariants":{"vocabulary":3914,"grammar":130,"lexical_pairs":859},"status":"verified candidate; not yet published"}
